SELECT game_id AS "gameId", ability_id AS "abilityId", provider_id AS "providerId", ability_key AS "abilityKey", ability_kind_type_id AS "abilityKindTypeId", display_name AS "displayName", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.ability_definitions WHERE game_id = #{gameId}
AND provider_id = #{providerId}
ORDER BY provider_id, ability_id
